import { Toaster, TooltipProvider } from '@cognite/aura/components';
import type { ReactNode } from 'react';

import { ChartAreaInteractive } from './chart-area-interactive';
import { documentRows } from './dashboard-template.data';
import { DataTable } from './data-table';
import { SectionCards } from './section-cards';
import { SiteHeader } from './site-header';

function DashboardTemplate(): ReactNode {
  return (
    <TooltipProvider>
      <div
        data-slot="dashboard-template"
        className="@container/main flex min-h-150 w-full min-w-0 flex-col overflow-hidden rounded-xl border bg-background"
      >
        <SiteHeader />
        <div className="flex min-w-0 flex-1 flex-col gap-4 overflow-auto p-4">
          <SectionCards />
          <ChartAreaInteractive />
          <DataTable data={documentRows} />
        </div>
      </div>
      <Toaster />
    </TooltipProvider>
  );
}

DashboardTemplate.displayName = 'DashboardTemplate';

export { DashboardTemplate };

import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from '@cognite/aura/chart';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardHeaderEnd,
  CardHeaderStart,
  CardTitle,
  SegmentedControl,
  SegmentedControlButton,
  SegmentedControlList,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@cognite/aura/components';
import type { ReactNode } from 'react';
import { useMemo, useState } from 'react';
import { Area, AreaChart, CartesianGrid, XAxis } from 'recharts';

import {
  chartReferenceDate,
  visitorChartData,
} from './dashboard-template.data';

const chartConfig = {
  visitors: {
    label: 'Visitors',
  },
  desktop: {
    label: 'Desktop',
    color: 'var(--color-chart-fjord-color-1)',
  },
  mobile: {
    label: 'Mobile',
    color: 'var(--color-chart-nordic-color-1)',
  },
} satisfies ChartConfig;

type TimeRange = '90d' | '30d' | '7d';

function isTimeRange(value: unknown): value is TimeRange {
  return value === '90d' || value === '30d' || value === '7d';
}

function formatChartDate(value: string): string {
  const date = new Date(`${value}T00:00:00`);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
  });
}

export function ChartAreaInteractive(): ReactNode {
  const [timeRange, setTimeRange] = useState<TimeRange>('90d');

  const filteredData = useMemo(() => {
    const referenceDate = new Date(`${chartReferenceDate}T00:00:00`);
    const daysToSubtract =
      timeRange === '30d' ? 30 : timeRange === '7d' ? 7 : 90;
    const startDate = new Date(referenceDate);
    startDate.setDate(startDate.getDate() - daysToSubtract);

    return visitorChartData.filter((item) => {
      const date = new Date(`${item.date}T00:00:00`);
      return date >= startDate;
    });
  }, [timeRange]);

  return (
    <Card data-slot="dashboard-chart">
      <CardHeader className="flex flex-col items-stretch gap-3 @3xl/main:flex-row @3xl/main:items-start @3xl/main:justify-between">
        <CardHeaderStart className="min-w-0">
          <CardTitle>Total Visitors</CardTitle>
          <CardDescription>
            {timeRange === '90d'
              ? 'Total for the last 3 months'
              : timeRange === '30d'
                ? 'Total for the last 30 days'
                : 'Total for the last 7 days'}
          </CardDescription>
        </CardHeaderStart>
        <CardHeaderEnd className="w-full @3xl/main:w-auto">
          <SegmentedControl
            value={timeRange}
            onValueChange={(value) => {
              if (isTimeRange(value)) {
                setTimeRange(value);
              }
            }}
            className="hidden @3xl/main:block"
          >
            <SegmentedControlList size="small">
              <SegmentedControlButton value="90d">
                Last 3 months
              </SegmentedControlButton>
              <SegmentedControlButton value="30d">
                Last 30 days
              </SegmentedControlButton>
              <SegmentedControlButton value="7d">
                Last 7 days
              </SegmentedControlButton>
            </SegmentedControlList>
          </SegmentedControl>
          <Select
            value={timeRange}
            onValueChange={(value) => {
              if (isTimeRange(value)) {
                setTimeRange(value);
              }
            }}
          >
            <SelectTrigger
              size="sm"
              className="w-40 @3xl/main:hidden"
              aria-label="Select time range"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="90d">Last 3 months</SelectItem>
              <SelectItem value="30d">Last 30 days</SelectItem>
              <SelectItem value="7d">Last 7 days</SelectItem>
            </SelectContent>
          </Select>
        </CardHeaderEnd>
      </CardHeader>
      <CardContent>
        <ChartContainer
          config={chartConfig}
          className="aspect-auto h-64 w-full"
          aria-label="Total visitors area chart"
        >
          <AreaChart accessibilityLayer data={filteredData}>
            <defs>
              <linearGradient id="fillDesktop" x1="0" y1="0" x2="0" y2="1">
                <stop
                  offset="5%"
                  stopColor="var(--color-desktop)"
                  stopOpacity={1}
                />
                <stop
                  offset="95%"
                  stopColor="var(--color-desktop)"
                  stopOpacity={0.1}
                />
              </linearGradient>
              <linearGradient id="fillMobile" x1="0" y1="0" x2="0" y2="1">
                <stop
                  offset="5%"
                  stopColor="var(--color-mobile)"
                  stopOpacity={0.8}
                />
                <stop
                  offset="95%"
                  stopColor="var(--color-mobile)"
                  stopOpacity={0.1}
                />
              </linearGradient>
            </defs>
            <CartesianGrid vertical={false} />
            <XAxis
              dataKey="date"
              tickLine={false}
              axisLine={false}
              tickMargin={8}
              minTickGap={32}
              tickFormatter={(value) =>
                typeof value === 'string' ? formatChartDate(value) : ''
              }
            />
            <ChartTooltip
              cursor={false}
              content={
                <ChartTooltipContent
                  indicator="dot"
                  labelFormatter={(value) =>
                    typeof value === 'string' ? formatChartDate(value) : ''
                  }
                />
              }
            />
            <Area
              dataKey="mobile"
              type="natural"
              fill="url(#fillMobile)"
              stroke="var(--color-mobile)"
              stackId="visitors"
            />
            <Area
              dataKey="desktop"
              type="natural"
              fill="url(#fillDesktop)"
              stroke="var(--color-desktop)"
              stackId="visitors"
            />
          </AreaChart>
        </ChartContainer>
      </CardContent>
    </Card>
  );
}

import {
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardHeaderEnd,
  CardHeaderStart,
  CardTitle,
  Count,
  CountUnit,
  CountValue,
} from '@cognite/aura/components';
import { cn } from '@cognite/aura/utils';
import { IconDotsVertical } from '@tabler/icons-react';
import { type ReactNode, useId } from 'react';

import {
  dashboardAssetCards,
  dashboardKpiCards,
  dashboardTrendCards,
  type DashboardTone,
} from './dashboard-layouts.data';

const sparklineTone: Record<DashboardTone, { stroke: string; color: string }> =
  {
    success: {
      stroke: 'stroke-success-foreground',
      color: 'var(--color-success-foreground)',
    },
    warning: {
      stroke: 'stroke-warning-foreground',
      color: 'var(--color-warning-foreground)',
    },
    critical: {
      stroke: 'stroke-critical-foreground',
      color: 'var(--color-critical-foreground)',
    },
    default: {
      stroke: 'stroke-neutral-foreground',
      color: 'var(--color-neutral-foreground)',
    },
  };

const toneDot: Record<DashboardTone, string> = {
  success: 'bg-success-foreground',
  warning: 'bg-warning-foreground',
  critical: 'bg-critical-foreground',
  default: 'bg-neutral-foreground',
};

function stepLine(points: readonly number[]): string {
  const min = Math.min(...points);
  const max = Math.max(...points);
  const span = max - min || 1;
  return points
    .map((value, index) => {
      const x = (index / (points.length - 1)) * 100;
      const y = 40 - ((value - min) / span) * 34;
      return index === 0 ? `M ${x} ${y}` : `H ${x} V ${y}`;
    })
    .join(' ');
}

function Sparkline({
  points,
  tone,
}: {
  points: readonly number[];
  tone: DashboardTone;
}): ReactNode {
  const line = stepLine(points);
  const colors = sparklineTone[tone];
  const gradientId = `sparkline-${useId().replace(/:/g, '')}`;
  return (
    <svg
      viewBox="0 0 100 44"
      preserveAspectRatio="none"
      aria-hidden="true"
      className="h-11 w-full"
    >
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="5%" stopColor={colors.color} stopOpacity={0.45} />
          <stop offset="100%" stopColor={colors.color} stopOpacity={0} />
        </linearGradient>
      </defs>
      <path d={`${line} V 44 H 0 Z`} fill={`url(#${gradientId})`} />
      <path
        d={line}
        fill="none"
        strokeWidth="1.5"
        vectorEffect="non-scaling-stroke"
        className={colors.stroke}
      />
    </svg>
  );
}

function StatusLine({
  status,
  tone,
}: {
  status: string;
  tone: DashboardTone;
}): ReactNode {
  return (
    <p className="flex items-center gap-1.5 text-sm leading-4.5 text-muted-foreground">
      <span className={cn('size-2 shrink-0 rounded-full', toneDot[tone])} />
      {status}
    </p>
  );
}

function AssetCard({ name, kind }: { name: string; kind: string }): ReactNode {
  return (
    <Card>
      <CardHeader>
        <CardHeaderStart className="h-auto pt-0">
          <div className="min-w-0">
            <CardTitle className="text-base leading-5 tracking-tighter">
              {name}
            </CardTitle>
            <CardDescription>{kind}</CardDescription>
          </div>
        </CardHeaderStart>
        <CardHeaderEnd>
          <Button
            variant="ghost"
            size="icon"
            aria-label={`More actions for ${name}`}
          >
            <IconDotsVertical size={16} stroke={1.5} />
          </Button>
        </CardHeaderEnd>
      </CardHeader>
    </Card>
  );
}

function TrendCard({
  title,
  status,
  tone,
  points,
  value,
  unit,
  className,
}: {
  title: string;
  status: string;
  tone: DashboardTone;
  points: readonly number[];
  value?: string;
  unit?: string;
  className?: string;
}): ReactNode {
  return (
    <Card className={cn('flex h-full flex-col', className)}>
      <CardHeader>
        <CardHeaderStart className="h-auto min-w-0 pt-0">
          <div className="min-w-0">
            <CardTitle className="text-base leading-5 tracking-tighter">
              {title}
            </CardTitle>
            <StatusLine status={status} tone={tone} />
          </div>
        </CardHeaderStart>
        {value && unit ? (
          <CardHeaderEnd>
            <Count variant={tone}>
              <CountValue>{value}</CountValue>
              <CountUnit>{unit}</CountUnit>
            </Count>
          </CardHeaderEnd>
        ) : null}
      </CardHeader>
      <CardContent className="mt-auto">
        <Sparkline points={points} tone={tone} />
      </CardContent>
    </Card>
  );
}

function DashboardOverviewCards(): ReactNode {
  const [firstTrend, secondTrend] = dashboardTrendCards;
  return (
    <div className="grid h-full min-w-0 grid-cols-1 gap-3 @3xl/main:grid-cols-2">
      <div className="flex min-h-0 min-w-0 flex-col gap-3">
        <AssetCard {...dashboardAssetCards[0]} />
        <AssetCard {...dashboardAssetCards[1]} />
        <TrendCard className="min-h-0 flex-1" {...firstTrend} />
      </div>
      <div className="flex min-h-0 min-w-0 flex-col gap-3">
        <AssetCard {...dashboardAssetCards[2]} />
        <AssetCard {...dashboardAssetCards[3]} />
        <TrendCard className="min-h-0 flex-1" {...secondTrend} />
      </div>
    </div>
  );
}

function DashboardKpiCards(): ReactNode {
  return (
    <section className="grid grid-cols-1 gap-3 @xl/main:grid-cols-2 @5xl/main:grid-cols-4">
      {dashboardKpiCards.map((card) => (
        <TrendCard key={`${card.title}-${card.status}`} {...card} />
      ))}
    </section>
  );
}

DashboardOverviewCards.displayName = 'DashboardOverviewCards';
DashboardKpiCards.displayName = 'DashboardKpiCards';

export { DashboardKpiCards, DashboardOverviewCards };

import {
  Badge,
  Button,
  CheckboxItem,
  CheckboxItemControl,
  Search,
} from '@cognite/aura/components';
import { cn } from '@cognite/aura/utils';
import { IconFilter, IconPlus } from '@tabler/icons-react';
import type { ReactNode } from 'react';

import { DashboardKpiCards } from './dashboard-layout-cards';
import {
  dashboardPrimaryAction,
  dashboardStatusVariant,
  dashboardWorkOrders,
  type DashboardWorkOrder,
} from './dashboard-layouts.data';

function DashboardLayoutGrid({
  showCheckboxes,
  showPrimary,
  selectedId,
  checkedIds,
  onSelectRow,
  onToggleRow,
  onToggleAll,
}: {
  showCheckboxes: boolean;
  showPrimary: boolean;
  selectedId: string | null;
  checkedIds: ReadonlySet<string>;
  onSelectRow: (id: string) => void;
  onToggleRow: (id: string, checked: boolean) => void;
  onToggleAll: (checked: boolean) => void;
}): ReactNode {
  const allChecked = dashboardWorkOrders.every((row) => checkedIds.has(row.id));

  return (
    <div className="flex min-w-0 flex-col gap-4">
      <DashboardKpiCards />
      <div className="flex flex-wrap items-center gap-2">
        <Search placeholder="Search work orders" className="w-56" />
        <Button variant="secondary">
          <IconFilter size={16} stroke={1.5} />
          Filters
        </Button>
        {showPrimary ? (
          <Button className="ml-auto">
            <IconPlus size={16} stroke={1.5} />
            {dashboardPrimaryAction}
          </Button>
        ) : null}
      </div>
      <div className="min-w-0 overflow-auto rounded-lg border">
        <table aria-label="Work orders" className="w-full text-sm">
          <thead className="bg-muted-background text-left text-muted-foreground">
            <tr>
              {showCheckboxes ? (
                <th className="w-10 px-3 py-2">
                  <CheckboxItem>
                    <CheckboxItemControl
                      checked={allChecked}
                      aria-label="Select all work orders"
                      onCheckedChange={(checked) =>
                        onToggleAll(checked === true)
                      }
                    />
                  </CheckboxItem>
                </th>
              ) : null}
              <th className="px-3 py-2 font-medium">Work order</th>
              <th className="px-3 py-2 font-medium">Area</th>
              <th className="px-3 py-2 font-medium">Priority</th>
              <th className="px-3 py-2 font-medium">Status</th>
              <th className="px-3 py-2 font-medium">Owner</th>
              <th className="px-3 py-2 font-medium">Due</th>
            </tr>
          </thead>
          <tbody>
            {dashboardWorkOrders.map((row) => (
              <WorkOrderRow
                key={row.id}
                row={row}
                showCheckboxes={showCheckboxes}
                selected={selectedId === row.id}
                checked={checkedIds.has(row.id)}
                onSelect={() => onSelectRow(row.id)}
                onToggle={(checked) => onToggleRow(row.id, checked)}
              />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function WorkOrderRow({
  row,
  showCheckboxes,
  selected,
  checked,
  onSelect,
  onToggle,
}: {
  row: DashboardWorkOrder;
  showCheckboxes: boolean;
  selected: boolean;
  checked: boolean;
  onSelect: () => void;
  onToggle: (checked: boolean) => void;
}): ReactNode {
  return (
    <tr
      className={cn(
        'border-t',
        selected && 'bg-accent-background',
        !showCheckboxes && 'cursor-pointer'
      )}
      onClick={showCheckboxes ? undefined : onSelect}
    >
      {showCheckboxes ? (
        <td className="px-3 py-2">
          <CheckboxItem>
            <CheckboxItemControl
              checked={checked}
              aria-label={`Select ${row.name}`}
              onCheckedChange={(value) => onToggle(value === true)}
            />
          </CheckboxItem>
        </td>
      ) : null}
      <td className="px-3 py-2">{row.name}</td>
      <td className="px-3 py-2">{row.area}</td>
      <td className="px-3 py-2">{row.priority}</td>
      <td className="px-3 py-2">
        <Badge variant={dashboardStatusVariant[row.status]} outline>
          {row.status}
        </Badge>
      </td>
      <td className="px-3 py-2">{row.owner}</td>
      <td className="px-3 py-2">{row.due}</td>
    </tr>
  );
}

DashboardLayoutGrid.displayName = 'DashboardLayoutGrid';

export { DashboardLayoutGrid };

import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from '@cognite/aura/chart';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardHeaderCenter,
  CardTitle,
} from '@cognite/aura/components';
import type { ReactNode } from 'react';
import { Area, AreaChart, CartesianGrid, XAxis } from 'recharts';

import { DashboardOverviewCards } from './dashboard-layout-cards';

const productionData = [
  { hour: '06:00', output: 142, target: 160 },
  { hour: '08:00', output: 168, target: 160 },
  { hour: '10:00', output: 181, target: 170 },
  { hour: '12:00', output: 174, target: 170 },
  { hour: '14:00', output: 190, target: 175 },
  { hour: '16:00', output: 184, target: 175 },
  { hour: '18:00', output: 171, target: 165 },
  { hour: '20:00', output: 163, target: 160 },
];

const productionConfig = {
  output: {
    label: 'Output',
    color: 'var(--color-chart-fjord-color-1)',
  },
  target: {
    label: 'Target',
    color: 'var(--color-chart-nordic-color-1)',
  },
} satisfies ChartConfig;

const mixData = [
  { month: 'Jan', oil: 186, gas: 80, condensate: 40 },
  { month: 'Feb', oil: 305, gas: 200, condensate: 90 },
  { month: 'Mar', oil: 237, gas: 120, condensate: 70 },
  { month: 'Apr', oil: 273, gas: 190, condensate: 85 },
  { month: 'May', oil: 209, gas: 130, condensate: 60 },
  { month: 'Jun', oil: 214, gas: 140, condensate: 75 },
];

const mixConfig = {
  oil: {
    label: 'Oil',
    color: 'var(--color-chart-fjord-color-1)',
  },
  gas: {
    label: 'Gas',
    color: 'var(--color-chart-nordic-color-1)',
  },
  condensate: {
    label: 'Condensate',
    color: 'var(--color-chart-aurora-color-1)',
  },
} satisfies ChartConfig;

function ChartCard({
  title,
  description,
  className,
  children,
}: {
  title: string;
  description: string;
  className?: string;
  children: ReactNode;
}): ReactNode {
  return (
    <Card className={className}>
      <CardHeader>
        <CardHeaderCenter>
          <CardTitle>{title}</CardTitle>
          <CardDescription>{description}</CardDescription>
        </CardHeaderCenter>
      </CardHeader>
      <CardContent className="min-h-0 flex-1">{children}</CardContent>
    </Card>
  );
}

function DashboardLayoutOverview({ scope }: { scope?: string }): ReactNode {
  return (
    <div className="flex min-w-0 flex-col gap-4">
      <div className="grid min-w-0 items-stretch gap-4 @4xl/main:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
        <DashboardOverviewCards />
        <ChartCard
          className="flex h-full min-w-0 flex-col"
          title="Production"
          description={scope ? `${scope} · tonnes per hour` : 'Tonnes per hour'}
        >
          <ChartContainer
            config={productionConfig}
            className="aspect-auto h-full min-h-56 w-full"
            aria-label="Production"
          >
            <AreaChart
              accessibilityLayer
              data={productionData}
              margin={{ left: 12, right: 12 }}
            >
              <CartesianGrid vertical={false} />
              <XAxis
                dataKey="hour"
                tickLine={false}
                tickMargin={8}
                axisLine={false}
              />
              <ChartTooltip
                cursor={false}
                content={<ChartTooltipContent indicator="line" />}
              />
              <Area
                dataKey="target"
                type="natural"
                fill="var(--color-target)"
                fillOpacity={0.25}
                stroke="var(--color-target)"
              />
              <Area
                dataKey="output"
                type="natural"
                fill="var(--color-output)"
                fillOpacity={0.35}
                stroke="var(--color-output)"
              />
            </AreaChart>
          </ChartContainer>
        </ChartCard>
      </div>
      <ChartCard
        className="min-w-0"
        title="Production mix"
        description="Oil, gas, and condensate for the first half of the year."
      >
        <ChartContainer
          config={mixConfig}
          className="aspect-auto h-64 w-full"
          aria-label="Production mix"
        >
          <AreaChart
            accessibilityLayer
            data={mixData}
            margin={{ left: 12, right: 12 }}
          >
            <CartesianGrid vertical={false} />
            <XAxis
              dataKey="month"
              tickLine={false}
              tickMargin={8}
              axisLine={false}
            />
            <ChartTooltip
              cursor={false}
              content={<ChartTooltipContent indicator="line" />}
            />
            <ChartLegend content={<ChartLegendContent />} />
            <Area
              dataKey="condensate"
              type="natural"
              fill="var(--color-condensate)"
              fillOpacity={0.3}
              stroke="var(--color-condensate)"
            />
            <Area
              dataKey="gas"
              type="natural"
              fill="var(--color-gas)"
              fillOpacity={0.3}
              stroke="var(--color-gas)"
            />
            <Area
              dataKey="oil"
              type="natural"
              fill="var(--color-oil)"
              fillOpacity={0.3}
              stroke="var(--color-oil)"
            />
          </AreaChart>
        </ChartContainer>
      </ChartCard>
    </div>
  );
}

DashboardLayoutOverview.displayName = 'DashboardLayoutOverview';

export { DashboardLayoutOverview };

import {
  Button,
  Item,
  ItemGroup,
  ItemSectionHeader,
  ItemSectionHeaderTitle,
  ItemTitle,
  Search,
} from '@cognite/aura/components';
import { IconFilter } from '@tabler/icons-react';
import type { ReactNode } from 'react';

import { dashboardPanelGroups } from './dashboard-layouts.data';

function DashboardLayoutPanel({
  scope,
  onScopeChange,
}: {
  scope: string;
  onScopeChange: (scope: string) => void;
}): ReactNode {
  return (
    <aside
      aria-label="Dashboard navigation"
      className="flex w-[240px] shrink-0 flex-col gap-3 border-r bg-background p-3"
    >
      <div className="flex items-center gap-2">
        <Search placeholder="Search" className="min-w-0 flex-1" />
        <Button variant="ghost" size="icon" aria-label="Filter">
          <IconFilter size={16} stroke={1.5} />
        </Button>
      </div>
      <nav className="flex min-h-0 flex-1 flex-col gap-3 overflow-auto">
        {dashboardPanelGroups.map((group) => (
          <ItemGroup key={group.title}>
            <ItemSectionHeader>
              <ItemSectionHeaderTitle>{group.title}</ItemSectionHeaderTitle>
            </ItemSectionHeader>
            {group.links.map((link) => (
              <Item
                key={link}
                selected={scope === link}
                onClick={() => onScopeChange(link)}
              >
                <ItemTitle>{link}</ItemTitle>
              </Item>
            ))}
          </ItemGroup>
        ))}
      </nav>
    </aside>
  );
}

DashboardLayoutPanel.displayName = 'DashboardLayoutPanel';

